START TRANSACTION;
ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),stackable=TRUE,active=TRUE,version=version+1;
CREATE TABLE one_day_subscription_reward_definitions(reward_code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,item_id BIGINT UNSIGNED NOT NULL,quantity BIGINT UNSIGNED NOT NULL,display_order INT UNSIGNED NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,PRIMARY KEY(reward_code),UNIQUE KEY uq_one_day_subscription_reward_item(item_id),CONSTRAINT fk_one_day_subscription_reward_item FOREIGN KEY(item_id) REFERENCES item_definitions(id),CONSTRAINT chk_one_day_subscription_reward_quantity CHECK(quantity>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE one_day_subscription_grants(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,operation_id BIGINT UNSIGNED NOT NULL,player_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NOT NULL,quantity BIGINT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uq_one_day_subscription_grant(operation_id,player_id,item_id),CONSTRAINT fk_one_day_subscription_grant_operation FOREIGN KEY(operation_id) REFERENCES operations(id),CONSTRAINT fk_one_day_subscription_grant_player FOREIGN KEY(player_id) REFERENCES players(id),CONSTRAINT fk_one_day_subscription_grant_item FOREIGN KEY(item_id) REFERENCES item_definitions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
COMMIT;
